'use strict';
let state, view='all', labelFilter='', query='', lastGoodQuery='', searchError='', temporaryOrder='', selected=new Set(), importItems=[], undoAction=null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const fmt=d=>new Intl.DateTimeFormat(undefined,{dateStyle:'medium'}).format(new Date(d));
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json'},...options});if(!r.ok)throw new Error('Request failed');return r.json()}
async function persist(){await api('/api/state',{method:'PUT',body:JSON.stringify(state)})}
function normalize(input){const u=new URL(input);if(!['http:','https:'].includes(u.protocol))throw Error();u.hash='';[...u.searchParams.keys()].forEach(k=>/^(utm_.+|fbclid|gclid|mc_cid|mc_eid)$/i.test(k)&&u.searchParams.delete(k));u.hostname=u.hostname.toLowerCase();if(u.pathname!=='/')u.pathname=u.pathname.replace(/\/+$/,'');return u.toString()}
function textOf(b){const d=document.createElement('div');d.innerHTML=b.noteHtml||'';return [b.title,b.description,d.textContent,b.site,b.pageText,...(b.labels||[])].filter(Boolean).join(' ').toLowerCase()}
function tokens(q){const out=[];let i=0;while(i<q.length){if(/\s/.test(q[i])){i++;continue}if(q[i]==='"'){let e=q.indexOf('"',i+1);if(e<0)throw Error('There is an unclosed quotation mark. Add the closing quote and try again.');out.push({t:'term',v:q.slice(i+1,e),quoted:true});i=e+1;continue}if('()'.includes(q[i])){out.push({t:q[i++]});continue}let e=i;while(e<q.length&&!/[\s()]/.test(q[e]))e++;let v=q.slice(i,e),u=v.toUpperCase();out.push(['AND','OR','NOT'].includes(u)?{t:u}:v[0]==='#'?{t:'label',v:v.slice(1)}:{t:'term',v});i=e}return out}
function compile(q){const ts=tokens(q.trim());if(!ts.length)return()=>true;const precise=ts.some(x=>['AND','OR','NOT','(',')'].includes(x.t));const atom=(x,b)=>x.t==='label'?(b.labels||[]).some(l=>l.toLowerCase()===x.v.toLowerCase()):textOf(b).includes(x.v.toLowerCase());if(!precise){const terms=ts.filter(x=>x.t==='term'),labels=ts.filter(x=>x.t==='label');return b=>terms.every(x=>atom(x,b))&&(!labels.length||labels.some(x=>atom(x,b)))}let p=0;const primary=()=>{const x=ts[p];if(!x)throw Error('The search ends before its last condition is complete.');if(x.t==='NOT'){p++;return{t:'not',a:primary()}}if(x.t==='('){p++;const n=or();if(ts[p]?.t!==')')throw Error('There is an unclosed parenthesis. Add “)” to complete the search.');p++;return n}if(['term','label'].includes(x.t)){p++;return x}throw Error(`“${x.t}” needs a search condition before it.`)};const start=x=>x&&['term','label','(','NOT'].includes(x.t);const and=()=>{let n=primary();while(p<ts.length&&(ts[p].t==='AND'||ts[p].t==='NOT'||start(ts[p]))){if(ts[p].t==='AND')p++;n={t:'and',a:n,b:primary()}}return n};const or=()=>{let n=and();while(ts[p]?.t==='OR'){p++;n={t:'or',a:n,b:and()}}return n};const tree=or();if(p!==ts.length)throw Error(ts[p].t===')'?'There is a closing parenthesis without a matching opening parenthesis.':'This search expression is incomplete.');const ev=(n,b)=>n.t==='not'?!ev(n.a,b):n.t==='and'?ev(n.a,b)&&ev(n.b,b):n.t==='or'?ev(n.a,b)||ev(n.b,b):atom(n,b);return b=>ev(tree,b)}
function activeItems(){let items=state.bookmarks.filter(b=>view==='archived'?b.archived:!b.archived);if(view==='later')items=items.filter(b=>b.readStatus==='later');if(view==='finished')items=items.filter(b=>b.readStatus==='finished');if(labelFilter)items=items.filter(b=>(b.labels||[]).includes(labelFilter));if(query&&!searchError){try{items=items.filter(compile(query))}catch{}}const order=temporaryOrder||state.preferences.order;return [...items].sort((a,b)=>order==='title'?a.title.localeCompare(b.title,undefined,{sensitivity:'base'}):order==='oldest'?new Date(a.createdAt)-new Date(b.createdAt):new Date(b.createdAt)-new Date(a.createdAt))}
function counts(){return{all:state.bookmarks.filter(b=>!b.archived).length,later:state.bookmarks.filter(b=>!b.archived&&b.readStatus==='later').length,finished:state.bookmarks.filter(b=>!b.archived&&b.readStatus==='finished').length,archived:state.bookmarks.filter(b=>b.archived).length}}
function labels(){const m={};state.bookmarks.filter(b=>!b.archived).forEach(b=>(b.labels||[]).forEach(l=>m[l]=(m[l]||0)+1));return Object.entries(m).sort((a,b)=>a[0].localeCompare(b[0]))}
function navButton(id,name,count){return`<button data-view="${id}" class="${view===id&&!labelFilter?'active':''}"><span>${name}</span><small>${count}</small></button>`}
function shell(){const c=counts();document.documentElement.style.setProperty('--text',state.preferences.textSize==='large'?'17px':state.preferences.textSize==='compact'?'13px':'15px');return`<div class="shell"><aside class="side"><div class="brand"><span class="mark"></span>Trove</div><nav class="nav">${navButton('all','All bookmarks',c.all)}${navButton('later','Read later',c.later)}${navButton('finished','Finished',c.finished)}${navButton('archived','Archived',c.archived)}<button data-view="preferences" class="${view==='preferences'?'active':''}"><span>Preferences</span></button><button data-view="transfer" class="${view==='transfer'?'active':''}"><span>Import & export</span></button></nav><div class="labels-nav"><div class="nav-title">Labels</div><div class="nav">${labels().map(([l,n])=>`<button data-label="${esc(l)}" class="${labelFilter===l?'active':''}"><span>${esc(l)}</span><small>${n}</small></button>`).join('')}</div></div><div class="saved-searches"><div class="nav-title">Saved searches</div><div class="nav">${state.savedSearches.map(s=>`<button class="saved-query" data-search="${s.id}"><span>${esc(s.name)}</span><small>${esc(s.query)}</small></button>`).join('')}</div></div></aside><main class="main"><header class="top"><form id="save-form" class="savebar"><input id="url" class="input url" aria-label="Web address" placeholder="Paste a web address to remember…"><button class="primary">Save bookmark</button></form><div class="save-options"><label><input id="save-later" type="checkbox"> Add to Read later</label><span id="save-error" class="error"></span></div></header><div id="content" class="content"></div></main></div>`}
function header(title,sub=''){return`<div class="heading"><div><div class="eyebrow">Your collection</div><h1>${esc(title)}</h1><div class="subtle">${esc(sub)}</div></div><div class="tools"><label><input id="select-all" type="checkbox"> Select all shown</label><select id="order" class="select" aria-label="Order"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></div></div>`}
function searchBox(){return`<div class="search-wrap"><form id="search-form" class="search-row"><input id="search" class="input" placeholder="Search titles, notes, labels, and saved pages" value="${esc(query)}"><button class="secondary">Search</button>${query?'<button type="button" class="quiet" id="save-search">Save this search</button>':''}</form><div class="hint">Try a word, <strong>#label</strong>, an “exact phrase”, or AND, OR, NOT and parentheses.</div>${searchError?`<div class="search-error">${esc(searchError)} Your earlier results are still shown.</div>`:''}</div>`}
function card(b){const labelChips=(b.labels||[]).slice(0,2).map(l=>`<span class="chip">${esc(l)}</span>`).join('')+((b.labels||[]).length>2?`<span class="chip">+${b.labels.length-2}</span>`:'');const reason=query&&!searchError?matchReason(b):'';return`<article class="card" id="bookmark-${b.id}"><input class="select-card" type="checkbox" aria-label="Select ${esc(b.title)}" data-select="${b.id}" ${selected.has(b.id)?'checked':''}><div class="cover">${b.image?`<img src="${esc(b.image)}" alt="">`:`<div class="fallback">${b.captureKind==='pdf'?'Saved PDF':'Saved page'}</div>`}</div><div class="card-body"><div class="site">${esc(b.site||new URL(b.url).hostname)} ${b.detailsUnavailable?' · Details unavailable':''}</div><h2>${esc(b.title||b.url)}</h2><p class="description">${esc(b.description||'No page description was available. You can add your own.')}</p><div class="chips">${labelChips}${b.readStatus==='later'?'<span class="chip">Read later</span>':''}</div>${b.noteHtml?`<div class="note"><strong>Your note</strong>${b.noteHtml}</div>`:''}${reason?`<div class="match">${reason}</div>`:''}${b.capturePath?`<div class="capture">Saved ${b.captureKind==='pdf'?'PDF':'page'} · ${fmt(b.capturedAt)}${b.captureSize?` · ${formatBytes(b.captureSize)}`:''} · searchable</div>`:''}<div class="card-actions"><button class="quiet" data-details="${b.id}">Show all details</button><button class="quiet" data-edit="${b.id}">Edit details</button>${b.readStatus==='later'?`<button class="quiet" data-finish="${b.id}">Mark read</button>`:''}${view==='archived'?`<button class="quiet" data-restore="${b.id}">Restore</button>`:`<button class="quiet" data-archive="${b.id}">Archive</button>`}<button class="quiet" data-delete="${b.id}">Delete</button></div></div></article>`}
function matchReason(b){const q=query.toLowerCase();const label=tokens(query).find(x=>x.t==='label'&&(b.labels||[]).some(l=>l.toLowerCase()===x.v.toLowerCase()));if(label)return`Matched label <strong>#${esc(label.v)}</strong>${/\bnot\b/i.test(query)?' and applied your exclusion':''}`;const words=tokens(query).filter(x=>x.t==='term').map(x=>x.v.toLowerCase());const page=(b.pageText||'').toLowerCase();const word=words.find(w=>page.includes(w));if(word){const i=page.indexOf(word);return`From saved page: …${esc((b.pageText||'').slice(Math.max(0,i-55),i+word.length+70))}…`}return`Matches your search across saved information.`}
function collection(){const names={all:'All bookmarks',later:'Read later',finished:'Finished',archived:'Archived'};let title=labelFilter?labelFilter:names[view];let items=activeItems();let sub=view==='later'?(items.length?`${items.length} waiting to be read`:'Your finished articles remain safely saved.'):view==='archived'?'Tucked away, not deleted.':`${items.length} shown · ${state.bookmarks.length} bookmarks kept`;let empty=view==='later'?`<div class="empty"><h2>You’re all caught up</h2><p>Finished articles are still saved in your collection.</p></div>`:query?`<div class="empty"><h2>Nothing matched “${esc(query)}”</h2><p>Try fewer words or a different label. Your search is still above so you can adjust it.</p></div>`:`<div class="empty"><h2>Nothing here yet</h2><p>Save a link above to begin.</p></div>`;$('#content').innerHTML=header(title,sub)+searchBox()+`<div class="bulk ${selected.size?'on':''}"><strong>${selected.size} selected</strong><input id="bulk-label" class="input" placeholder="Add a label"><button id="bulk-add" class="secondary">Add label</button><button id="bulk-archive" class="secondary">Archive</button></div><div class="cards">${items.length?items.slice(0,state.preferences.pageSize).map(card).join(''):empty}</div>`;$('#order').value=temporaryOrder||state.preferences.order;bindCollection()}
function transfer(){view='transfer';$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">Your collection</div><h1>Bring bookmarks in—or take them with you.</h1><p class="subtle">Nothing changes until you review and confirm an import. Exporting never changes your collection.</p></div></div><div class="prefs"><section class="panel"><h2>Import browser bookmarks</h2><p>Choose the HTML bookmark file exported by your browser. Folder names become labels, while original titles and dates are kept.</p><input id="import-file" type="file" accept=".html,text/html"><div id="import-review"></div></section><section class="panel"><h2>Export your collection</h2><p>Browser file includes links, titles, dates and labels. A complete backup also contains notes, statuses and preserved files.</p><p><a class="primary" href="/api/export/browser">Download browser file</a></p><p><a class="secondary" href="/api/export/complete">Download complete backup</a></p></section></div>`;bindTransfer()}
function preferences(){view='preferences';const p=state.preferences;$('#content').innerHTML=`<div class="heading"><div><div class="eyebrow">Your preferences</div><h1>Make the collection feel like yours.</h1><p class="subtle">These become defaults; an individual view can still be reordered temporarily.</p></div></div><div class="prefs"><section class="panel"><label class="field"><span>Bookmarks shown at once</span><select id="pref-size" class="select"><option value="12">12 bookmarks</option><option value="24">24 bookmarks</option><option value="48">48 bookmarks</option></select></label><label class="field"><span>Default order</span><select id="pref-order" class="select"><option value="newest">Newest first</option><option value="oldest">Oldest first</option><option value="title">Title A–Z</option></select></label><label class="field"><span>Text size</span><select id="pref-text" class="select"><option value="compact">Compact</option><option value="comfortable">Comfortable</option><option value="large">Large</option></select></label><button id="pref-save" class="primary">Save preferences</button></section><section id="pref-preview" class="panel preview"><h2>Preview</h2><p id="pref-summary"></p><h3>Recipes I want to try</h3><p>The bookmark itself does not change—only how your collection is presented.</p></section></div>`;$('#pref-size').value=p.pageSize;$('#pref-order').value=p.order;$('#pref-text').value=p.textSize;const preview=()=>{$('#pref-summary').textContent=`${$('#pref-size').value} at once · ${$('#pref-order').selectedOptions[0].text}`;$('#pref-preview').className=`panel preview ${$('#pref-text').value}`};['#pref-size','#pref-order','#pref-text'].forEach(x=>$(x).onchange=preview);preview();$('#pref-save').onclick=async()=>{state.preferences={pageSize:Number($('#pref-size').value),order:$('#pref-order').value,textSize:$('#pref-text').value};await persist();toast('Preferences saved. New views will use these defaults.');render()}}
function render(){const app=$('#app');app.innerHTML=shell();bindShell();if(view==='preferences')preferences();else if(view==='transfer')transfer();else collection();app.querySelector('.shell').dataset.harnessReady='true'}
function bindShell(){document.querySelectorAll('[data-view]').forEach(x=>x.onclick=()=>{view=x.dataset.view;labelFilter='';query='';searchError='';selected.clear();temporaryOrder='';render()});document.querySelectorAll('[data-label]').forEach(x=>x.onclick=()=>{view='all';labelFilter=x.dataset.label;query='';selected.clear();render()});document.querySelectorAll('[data-search]').forEach(x=>x.onclick=()=>{const s=state.savedSearches.find(y=>y.id===x.dataset.search);view='all';labelFilter='';query=s.query;lastGoodQuery=query;selected.clear();render();toast(`Reran “${s.name}” against your current collection.`)});$('#save-form').onsubmit=saveBookmark}
function bindCollection(){const items=activeItems();$('#order').onchange=e=>{temporaryOrder=e.target.value;render()};$('#select-all').onchange=e=>{selected=new Set(e.target.checked?items.map(x=>x.id):[]);render()};document.querySelectorAll('[data-select]').forEach(x=>x.onchange=()=>{x.checked?selected.add(x.dataset.select):selected.delete(x.dataset.select);render()});$('#search-form').onsubmit=e=>{e.preventDefault();const next=$('#search').value;try{compile(next);query=next;lastGoodQuery=next;searchError='';selected.clear();render()}catch(err){query=lastGoodQuery;searchError=err.message;render();$('#search').value=next}};$('#save-search')?.addEventListener('click',()=>modalSaveSearch());document.querySelectorAll('[data-edit]').forEach(x=>x.onclick=()=>modalEdit(x.dataset.edit));document.querySelectorAll('[data-details]').forEach(x=>x.onclick=()=>modalDetails(x.dataset.details));document.querySelectorAll('[data-finish]').forEach(x=>x.onclick=()=>finish(x.dataset.finish));document.querySelectorAll('[data-archive]').forEach(x=>x.onclick=()=>archive([x.dataset.archive]));document.querySelectorAll('[data-restore]').forEach(x=>x.onclick=()=>restore(x.dataset.restore));document.querySelectorAll('[data-delete]').forEach(x=>x.onclick=()=>modalDelete(x.dataset.delete));$('#bulk-add')?.addEventListener('click',bulkAdd);$('#bulk-archive')?.addEventListener('click',()=>archive([...selected]))}
async function saveBookmark(e){e.preventDefault();const input=$('#url'),err=$('#save-error');err.textContent='';let n;try{n=normalize(input.value)}catch{err.textContent='That doesn’t look like a complete web address. Try https://example.com/article';input.setAttribute('aria-invalid','true');return}const existing=state.bookmarks.find(b=>b.normalizedUrl===n);if(existing){view=existing.archived?'archived':'all';query='';render();setTimeout(()=>{$(`#bookmark-${CSS.escape(existing.id)}`)?.classList.add('focus')},0);toast('You already saved this link. Here’s the existing bookmark.');return}const readLater=$('#save-later').checked;input.disabled=true;let cap=await api('/api/capture',{method:'POST',body:JSON.stringify({url:input.value})});const now=new Date().toISOString(),u=new URL(input.value);const b={id:uid(),url:input.value,normalizedUrl:n,site:cap.site||u.hostname.replace(/^www\./,''),title:cap.title||input.value,description:cap.description||'',image:cap.image||'',labels:[],noteHtml:'',pageText:cap.pageText||'',createdAt:now,capturedAt:cap.capturedAt||now,capturePath:cap.capturePath||'',captureKind:cap.captureKind||'',captureSize:cap.captureSize||0,detailsUnavailable:!!cap.error,readStatus:readLater?'later':null,archived:false};state.bookmarks.push(b);await persist();input.value='';input.disabled=false;view=readLater?'later':'all';render();toast(cap.error?'Link saved. Page details are unavailable; you can edit them or retry later.':'Bookmark saved with a searchable copy.')}
function modal(html){const back=document.createElement('div');back.className='modal-back';back.innerHTML=`<div class="modal">${html}</div>`;document.body.append(back);back.addEventListener('click',e=>{if(e.target===back)back.remove()});return back}
function modalEdit(id){const b=state.bookmarks.find(x=>x.id===id), all=labels().map(x=>x[0]);const m=modal(`<h2>Edit bookmark</h2><label class="field"><span>Web address</span><input id="e-url" class="input" value="${esc(b.url)}"></label><label class="field"><span>Title</span><input id="e-title" class="input" value="${esc(b.title)}"></label><label class="field"><span>Description</span><textarea id="e-desc" class="input">${esc(b.description)}</textarea></label><div class="field"><span>Labels</span><div class="chips" id="e-chips"></div><div class="label-editor"><input id="e-label" class="input" placeholder="Type a label"><div id="e-suggest" class="label-suggestions"></div></div></div><div class="field"><span>Your note</span><div class="editor-tools"><button type="button" data-cmd="bold"><b>Bold</b></button><button type="button" data-cmd="insertUnorderedList">• List</button></div><div id="e-note" class="editor" contenteditable="true">${b.noteHtml||''}</div></div><div class="modal-actions"><button class="secondary" data-close>Cancel</button><button id="e-save" class="primary">Save changes</button></div>`);let current=[...(b.labels||[])];const chips=()=>{$('#e-chips').innerHTML=current.map(l=>`<span class="chip">${esc(l)} <button data-rm="${esc(l)}" class="quiet" aria-label="Remove ${esc(l)}">×</button></span>`);m.querySelectorAll('[data-rm]').forEach(x=>x.onclick=()=>{current=current.filter(l=>l!==x.dataset.rm);chips()})};chips();$('#e-label').oninput=()=>{const q=$('#e-label').value.trim().toLowerCase();$('#e-suggest').innerHTML=q?all.filter(l=>l.toLowerCase().includes(q)&&!current.includes(l)).map(l=>`<button data-add="${esc(l)}">${esc(l)}</button>`).join('')+`<button data-add="${esc($('#e-label').value.trim())}">Add “${esc($('#e-label').value.trim())}”</button>`:'';m.querySelectorAll('[data-add]').forEach(x=>x.onclick=()=>{const name=all.find(l=>l.toLowerCase()===x.dataset.add.toLowerCase())||x.dataset.add;if(name&&!current.some(l=>l.toLowerCase()===name.toLowerCase()))current.push(name);$('#e-label').value='';$('#e-suggest').innerHTML='';chips()})};m.querySelectorAll('[data-cmd]').forEach(x=>x.onclick=()=>document.execCommand(x.dataset.cmd));m.querySelector('[data-close]').onclick=()=>m.remove();$('#e-save').onclick=async()=>{const nextUrl=$('#e-url').value;let norm;try{norm=normalize(nextUrl)}catch{toast('Use a complete web address, such as https://example.com/article');return}const changed=norm!==b.normalizedUrl;if($('#e-title').value!==b.title)b.personalizedTitle=true;if($('#e-desc').value!==b.description)b.personalizedDescription=true;if(changed){const cap=await api('/api/capture',{method:'POST',body:JSON.stringify({url:nextUrl})});b.url=nextUrl;b.normalizedUrl=norm;b.site=cap.site||new URL(nextUrl).hostname;b.image=cap.image||b.image;b.pageText=cap.pageText||b.pageText;b.capturePath=cap.capturePath||b.capturePath;b.capturedAt=cap.capturedAt||b.capturedAt;if(!b.personalizedTitle)b.title=cap.title||b.title;if(!b.personalizedDescription)b.description=cap.description||b.description}else{b.title=$('#e-title').value;b.description=$('#e-desc').value}b.labels=current;b.noteHtml=$('#e-note').innerHTML;await persist();m.remove();render();toast('Bookmark updated. Your own wording stays yours.')}}
